insert into public.menu_items
  (business_id, category_id, name, price, tax_mode, description, is_beverage, position) values
  ('fc3065c8-cb40-45ad-bec1-aecb388001c1', 'ffb6c3ee-f48e-486d-8713-11782b34cbf9', 'Picadera de salchichas picantes', 350.00, 'exclusive', 'Salchichas sazonadas con especias cuidadosamente seleccionadas, con un equilibrio perfecto entre el calor y el sabor.', false, 1),
  ('fc3065c8-cb40-45ad-bec1-aecb388001c1', 'ffb6c3ee-f48e-486d-8713-11782b34cbf9', 'Picadera de embutidos & quesos', 850.00, 'exclusive', 'Deliciosa variedad de embutidos y quesos de calidad premium.', false, 2),
  ('fc3065c8-cb40-45ad-bec1-aecb388001c1', 'ffb6c3ee-f48e-486d-8713-11782b34cbf9', 'Eco Tartar', 750.00, 'exclusive', 'Tartar de atún fresco en salsa de la casa, cubos de aguacate y platanitos crocantes.', false, 3),
  ('fc3065c8-cb40-45ad-bec1-aecb388001c1', 'ffb6c3ee-f48e-486d-8713-11782b34cbf9', 'Brocheta de Pollo', 350.00, 'exclusive', 'Sellada al fuego vivo en grill, marinada con hierbas, ajo y limón, con cubo de vegetales frescos y salsa de ajo y cilantro.', false, 4),
