  ('fc3065c8-cb40-45ad-bec1-aecb388001c1', 'ffb6c3ee-f48e-486d-8713-11782b34cbf9', 'Brocheta Mixta', 450.00, 'exclusive', 'Sellada al fuego vivo en grill, marinada con hierbas, ajo y limón, con cubo de vegetales frescos y salsa de ajo y cilantro.', false, 6),
  ('fc3065c8-cb40-45ad-bec1-aecb388001c1', 'ffb6c3ee-f48e-486d-8713-11782b34cbf9', 'Canasticas de Birria (3 Unid)', 650.00, 'exclusive', 'Canastas de plátanos, birria reducida a 45m, queso mixto gratinado, sobre base de guacamole.', false, 7),
  ('fc3065c8-cb40-45ad-bec1-aecb388001c1', 'ffb6c3ee-f48e-486d-8713-11782b34cbf9', 'Canasticas de Camarones (3 Unid)', 700.00, 'exclusive', 'Canastas de plátanos, camarones salteados en licor de coco, base de guacamole, queso mozzarella gratinado y pico de gallo.', false, 8),
  ('fc3065c8-cb40-45ad-bec1-aecb388001c1', 'ffb6c3ee-f48e-486d-8713-11782b34cbf9', 'Calamares fritos (7 Unid)', 350.00, 'exclusive', 'Aros de calamares rebozados, con salsa tártara o picante hecha en casa.', false, 9),
