  ('fc3065c8-cb40-45ad-bec1-aecb388001c1', '06eba2de-dded-4e2e-a2a4-86166f53ebf6', 'Tacos Hermanos Trejo (3 Unid)', 450.00, 'exclusive', 'Pollo desmechado con vegetales mixtos y queso mozzarella gratinado. Salsa picante aparte.', false, 3),
